import{_ as t,o as i,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-01-08","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-01-08","date":"2025-01-08T00:00:00.000Z","updated":"2025-02-27T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","时间戳精度","数据损坏修复"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-01-08.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-01-08.md","lastUpdated":1780460162000}'),a={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-01-08.md"};function r(s,e,n,g,d,c){return i(),l("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>: 2025年1月8日 <strong>会议主题</strong>: Ceph RGW 相关问题讨论 <strong>参会人员</strong>: Ogazon, KC, Casey, Jesse 等</p><h4 id="_1-关于-rgw-中-last-modified-time-stamps-的问题" tabindex="-1">1. <strong>关于 RGW 中 Last Modified Time Stamps 的问题</strong> <a class="header-anchor" href="#_1-关于-rgw-中-last-modified-time-stamps-的问题" aria-label="Permalink to &quot;1. **关于 RGW 中 Last Modified Time Stamps 的问题**&quot;">​</a></h4><ul><li><strong>背景</strong>: <ul><li>某客户使用 Apache Flink 和 Java AWS SDK，在通过 RGW 进行对象存储操作时，发现 <code>head object</code> API 和 <code>list objects</code> API 返回的时间戳精度不一致，导致 Flink 误判对象需要重新上传。</li><li><code>head object</code> API 返回的时间戳遵循 RFC 格式，仅精确到秒，而 <code>list objects</code> API 返回的时间戳则精确到毫秒。</li></ul></li><li><strong>问题</strong>: <ul><li>RGW 返回的时间戳毫秒部分不为零，导致与 AWS 的行为不一致，Flink 无法正确比较时间戳。</li></ul></li><li><strong>讨论</strong>: <ul><li>在 RGW 的 ISO 8601 函数中将毫秒部分置零，以解决此问题。</li><li>KC 提出，RGW 的 ISO 8601 函数不仅用于 S3 API，还用于其他协议，因此建议仅在 S3 API 中进行修改。</li><li>讨论了是否需要引入配置项来控制时间戳精度，但最终认为不需要。</li></ul></li><li><strong>决定</strong>: <ul><li>将在 S3 API 中对时间戳进行截断，仅保留秒级精度，并在 PR 中继续讨论。</li></ul></li></ul><h4 id="_2-关于-rgw-数据损坏问题" tabindex="-1">2. <strong>关于 RGW 数据损坏问题</strong> <a class="header-anchor" href="#_2-关于-rgw-数据损坏问题" aria-label="Permalink to &quot;2. **关于 RGW 数据损坏问题**&quot;">​</a></h4><ul><li><strong>背景</strong>: <ul><li>最近发现一个潜在的数据损坏问题，当 RGW 发起的 RADOS 操作超时时，可能会导致数据丢失。</li><li>该问题已在 Reef 版本中修复，但尚未向后移植到 Squid 版本。</li></ul></li><li><strong>讨论</strong>: <ul><li>该问题仅在启用 RADOS 层超时设置时才会出现，默认情况下不会影响用户。</li><li>Casey 提到，RADOS 层超时设置可能会导致数据丢失或孤儿数据，因此不建议全局启用超时。</li><li>讨论了是否可以将超时设置仅限于 GET 操作，而不是 PUT 操作。</li></ul></li><li><strong>决定</strong>: <ul><li>将在 Squid 版本的 Tracker 中创建问题，并尽快向后移植数据损坏修复。</li><li>不将此修复作为 Squid 版本的阻塞项，因为默认情况下不会影响用户。</li></ul></li></ul><h4 id="_3-其他议题" tabindex="-1">3. <strong>其他议题</strong> <a class="header-anchor" href="#_3-其他议题" aria-label="Permalink to &quot;3. **其他议题**&quot;">​</a></h4><ul><li><strong>会议 URL 稳定性</strong>: <ul><li>Jesse 确认会议 URL 保持稳定，已正确记录在日历中。</li></ul></li></ul><p><strong>后续行动计划</strong>:</p><ol><li>在 RGW 的 S3 API 中对时间戳进行截断，仅保留秒级精度，并在 PR 中继续讨论。</li><li>在 Squid 版本的 Tracker 中创建问题，并尽快向后移植数据损坏修复。</li><li>继续讨论 RADOS 层超时设置的优化方案，可能仅对 GET 操作启用超时。</li></ol><p><strong>会议结束时间</strong>: 不详</p>',11)])])}const p=t(a,[["render",r]]);export{u as __pageData,p as default};
